/// <summary>
/// PricingAttribute that is calculated based on table <c>PdsCatchWeightItem</c> field ItemId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
/// [GUPPricingAttributeFieldsDiscovery(fieldStr(PdsCatchWeightItem, ItemId))]
internal class GUPPricingAttributePdsCatchWeightItemItemIdIsPdsCWItem extends GUPPricingAttributePdsCatchWeightItem implements GUPIPricingAttribute
{
}

Method.Source:
    private boolean isPdsCWItem(ItemId  _itemId)
    {
        PdsCatchWeightItem pdsCatchWeightItem;

        return _itemId
            && (select firstonly pdsCatchWeightItem
                    where pdsCatchWeightItem.ItemId == _itemId).RecId != 0;
    }

public str getName()
{
    return fieldPName(PdsCatchWeightItem, ItemId);
}
